/**
 * A personal or CLI token, without its secret
 */
export type Token = {
    id: string;
    name: string;
    /**
     * `personal`, `cli` or `mobile` (the phone app's)
     */
    kind: string;
    scopes: Array<string>;
    /**
     * The first characters of its secret
     */
    hint: string;
    createdAt: string;
    expiresAt: string | null;
    /**
     * Precise to five minutes
     */
    lastUsedAt: string | null;
};

/**
 * A personal token to create
 */
export type TokenCreate = {
    /**
     * 1 to 100 characters
     */
    name: string;
    /**
     * `resource:action`, 1 to 32
     */
    scopes: Array<string>;
    /**
     * 1 to 366; no expiry when absent
     */
    expiresInDays?: number | null;
};

/**
 * The live tokens, newest first
 */
export type TokenList = {
    tokens: Array<Token>;
};

/**
 * The answer of a read or a change of a session's todo
 */
export type SessionTodo = {
    /**
     * The list; null while the session has none
     */
    todo: Todo | null;
};

/**
 * The answer of `startTodoItem`
 */
export type StartTodoItemResponse = {
    todo: Todo;
    /**
     * `<!-- ostrom-todo: <list8>/<item> -->`, `list8` the first 8 characters of the list's id: put it in the body of the item's pull request, which the checks find by it whatever its number
     */
    marker: string;
};

/**
 * A session's todo: the plan reference and its items, each with a complete description and a typed end condition (`todos.v1`). An item is done only when its checks pass; items are added, never deleted
 */
export type Todo = {
    id: string;
    /**
     * The session's root id: a reopened segment (`~r<n>`) keeps its list
     */
    sessionId: string;
    /**
     * One paragraph pointing to the full plan, shown to the agent at every stop
     */
    reference: string;
    refs?: Array<WaitRef>;
    status: TodoStatus;
    /**
     * Blocked stops in a row without progress; at 3 a wait asks the owner (0 when absent)
     */
    stall?: number;
    items: Array<TodoItem>;
    createdAt: string;
    updatedAt: string;
    /**
     * The first `todo` item whose dependencies are done or dropped; absent when none
     */
    nextItemId?: string;
    /**
     * What the Stop hook recorded about itself, oldest first (the newest 20)
     */
    hookEvents?: Array<TodoHookEvent>;
};

/**
 * `done`: every item is done or dropped and the final verification held
 */
export type TodoStatus = 'active' | 'done' | 'abandoned' | (string & {});

/**
 * An item of a todo, as the server keeps it
 */
export type TodoItem = {
    id: string;
    name: string;
    description: string;
    doneWhen: TodoDoneWhen;
    dependsOn?: Array<string>;
    origin: TodoItemOrigin;
    /**
     * Why a discovered item was added
     */
    originReason?: string;
    status: TodoItemStatus;
    proof?: TodoProof;
    notes?: Array<TodoNote>;
    dropReason?: string;
    /**
     * The wait that asks the session's owner about the drop
     */
    dropWaitId?: string;
    links?: Array<TodoLink>;
    /**
     * Every check of the condition is `attested`: nothing verifies it (false when absent)
     */
    unverified?: boolean;
};

/**
 * `plan`: written with the list; `discovered`: added on the way
 */
export type TodoItemOrigin = 'plan' | 'discovered' | (string & {});

/**
 * `drop_requested`: a wait asks the owner; `dropped`: on the owner's yes, never deleted
 */
export type TodoItemStatus = 'todo' | 'doing' | 'done' | 'drop_requested' | 'dropped' | (string & {});

/**
 * An item as the agent writes it
 */
export type TodoItemInput = {
    /**
     * A slug of at most 40 characters (`[a-z0-9][a-z0-9-]*`), unique in the list
     */
    id: string;
    /**
     * One line, at most 80 characters
     */
    name: string;
    /**
     * 80 to 4 000 characters: what, where, why, what is out of scope; enough for a new agent to do it alone
     */
    description: string;
    doneWhen: TodoDoneWhen;
    /**
     * Ids of the items that must be done or dropped before this one starts
     */
    dependsOn?: Array<string>;
};

/**
 * The end condition of an item, frozen once created
 */
export type TodoDoneWhen = {
    /**
     * What "done" means, at most 1 000 characters
     */
    text: string;
    /**
     * At least one typed check
     */
    checks: Array<TodoCheck>;
};

/**
 * One typed check of an end condition, told apart by `type`. A check is read again at every stop, so it must stay true once the work moves on (never a transient state such as a PR still open); no check names a PR number or a version. `pr_merged`, `pr_closed`, `release_contains`, `ci_green` (with `gh`) and `command` (in a shell) run on the agent's machine; `artifact_published` and `wait_answered` are verified by the server through the item's links; `attested` is the agent's word, the last resort. A client shows a `type` it does not know as text
 */
export type TodoCheck = ({
    type: 'pr_merged';
} & TodoCheckPrMerged) | ({
    type: 'pr_closed';
} & TodoCheckPrClosed) | ({
    type: 'release_contains';
} & TodoCheckReleaseContains) | ({
    type: 'ci_green';
} & TodoCheckCiGreen) | ({
    type: 'command';
} & TodoCheckCommand) | ({
    type: 'artifact_published';
} & TodoCheckArtifactPublished) | ({
    type: 'wait_answered';
} & TodoCheckWaitAnswered) | ({
    type: 'attested';
} & TodoCheckAttested);

/**
 * The item's pull request (linked, or found by its marker among the PRs of the token's login) is merged
 */
export type TodoCheckPrMerged = {
    type: 'pr_merged';
    /**
     * `owner/name`
     */
    repo: string;
};

/**
 * The item's pull request is closed without merge, for the stated reason
 */
export type TodoCheckPrClosed = {
    type: 'pr_closed';
    repo: string;
    /**
     * At most 1 000 characters
     */
    reason: string;
};

/**
 * The earliest published, non-draft release of `repo` whose tag is at or ahead of the merge commit of the item `of` (or of `commit`); it is linked to the item with its tag
 */
export type TodoCheckReleaseContains = {
    type: 'release_contains';
    repo: string;
    /**
     * The id of the item whose pull request's merge commit the release must contain
     */
    of?: string;
    commit?: string;
};

/**
 * Every workflow run of `repo` on the merge commit of the item `of` (or on `ref`) completed green; none yet, running or failed is not done
 */
export type TodoCheckCiGreen = {
    type: 'ci_green';
    repo: string;
    of?: string;
    ref?: string;
    /**
     * Only the runs of this workflow
     */
    workflow?: string;
};

/**
 * A command run on the agent's machine (`sh -c`, `cmd /c` on Windows) exits with `expectExit`. `run` may cite `${pr:<item>.number}`, `${pr:<item>.mergeSha}` and `${release:<item>.tag}`, replaced from the links; a value not linked yet leaves the check unknown. Output bounded to 300 characters and masked
 */
export type TodoCheckCommand = {
    type: 'command';
    /**
     * At most 2 000 characters
     */
    run: string;
    cwd?: string;
    /**
     * 0 when absent
     */
    expectExit?: number;
    /**
     * 60 when absent
     */
    timeoutSeconds?: number;
};

/**
 * The artifact `id` (or the one linked to the item) is published, at `minVersion` or later; verified by the server
 */
export type TodoCheckArtifactPublished = {
    type: 'artifact_published';
    id?: string;
    minVersion?: number;
};

/**
 * The wait linked to the item is answered, with `action` when given; verified by the server
 */
export type TodoCheckWaitAnswered = {
    type: 'wait_answered';
    action?: string;
};

/**
 * The agent's word for `what`: nothing verifies it, the item is shown as not verified
 */
export type TodoCheckAttested = {
    type: 'attested';
    /**
     * At most 1 000 characters
     */
    what: string;
};

/**
 * What the check at `index` of the item's stored condition observed
 */
export type TodoCheckReport = {
    index: number;
    /**
     * true passed, false failed, absent unknown (unreachable, not linked yet): only true counts
     */
    passed?: boolean;
    /**
     * At most 2 000 characters
     */
    observed: string;
    /**
     * At most 10 https addresses
     */
    urls?: Array<string>;
};

/**
 * The last verification of an item, kept when it refused
 */
export type TodoProof = {
    at: string;
    /**
     * true passed, false failed, absent unknown
     */
    passed?: boolean;
    text: string;
    urls?: Array<string>;
};

/**
 * A dated note of an item; notes are only appended
 */
export type TodoNote = {
    at: string;
    text: string;
};

export type TodoLinkKind = 'pr' | 'release' | 'artifact' | 'wait' | (string & {});

/**
 * A link of an item, frozen once bound
 */
export type TodoLink = {
    kind: TodoLinkKind;
    /**
     * The https address of a pull request or a release, or the id of an artifact or a wait
     */
    ref: string;
    number?: number;
    /**
     * A pull request's merge commit
     */
    sha?: string;
    /**
     * A release's tag
     */
    tag?: string;
    at: string;
};

/**
 * `blocked`: the third stop without progress opened a wait; `hook_error`: the hook failed open
 */
export type TodoHookEventKind = 'blocked' | 'hook_error' | (string & {});

export type TodoHookEvent = {
    at: string;
    kind: TodoHookEventKind;
    text: string;
};

export type CreateTodoRequest = {
    /**
     * The session, named by its owner or by its agent token
     */
    sessionId?: string;
    /**
     * One paragraph pointing to the full plan (an artifact link, or the person's request as is), at most 4 000 characters
     */
    reference: string;
    /**
     * At most 10 links shown with the reference
     */
    refs?: Array<WaitRef>;
    /**
     * Every step of the plan, in order, at most 500
     */
    items: Array<TodoItemInput>;
};

export type AddTodoItemRequest = {
    sessionId?: string;
    item: TodoItemInput;
    /**
     * Why the plan needs it, at most 1 000 characters
     */
    reason: string;
};

export type StartTodoItemRequest = {
    sessionId?: string;
    /**
     * The item is given to a background agent; the item in progress stays in progress (false when absent)
     */
    background?: boolean;
    /**
     * The background agent's name
     */
    agent?: string;
};

export type NoteTodoItemRequest = {
    sessionId?: string;
    /**
     * At most 2 000 characters
     */
    text: string;
};

export type DropTodoItemRequest = {
    sessionId?: string;
    /**
     * Why the item no longer makes sense, at most 1 000 characters
     */
    reason: string;
};

export type LinkTodoItemRequest = {
    sessionId?: string;
    kind: TodoLinkKind;
    /**
     * The https address of a pull request or a release, or the id of an artifact or a wait
     */
    ref: string;
    number?: number;
    sha?: string;
    tag?: string;
    /**
     * Replace a pull request closed without merge (false when absent)
     */
    replaceClosed?: boolean;
};

export type CompleteTodoItemRequest = {
    sessionId?: string;
    /**
     * One report per position of the stored condition
     */
    checks: Array<TodoCheckReport>;
};

/**
 * The reminder block of a session's todo
 */
export type TodoContext = {
    /**
     * The reference, the item in progress (else the next one) and the list; null without an active list
     */
    text: string | null;
};

export type TodoStopPhase = 'begin' | 'verify' | 'settle' | (string & {});

/**
 * The outcome of the checks the Stop hook ran for one item
 */
export type TodoStopItemReport = {
    itemId: string;
    /**
     * By position in the item's stored condition
     */
    checks?: Array<TodoCheckReport>;
};

/**
 * One stop of the agent, asked by the Stop hook
 */
export type TodoStopRequest = {
    sessionId?: string;
    /**
     * `begin` when absent
     */
    phase?: TodoStopPhase;
    /**
     * A background task or a scheduled wake-up of the session still runs (false when absent)
     */
    background?: boolean;
    /**
     * `verify`: the checks of the item in progress and of the `todo` items whose checks are all cheap; `settle`: every check of the done items. Each item once, at most 500
     */
    items?: Array<TodoStopItemReport>;
    /**
     * `verify`: the https addresses of the pull requests the session opened, at most 5
     */
    orphans?: Array<string>;
    /**
     * The agent's last message, kept to 2 000 characters
     */
    lastMessage?: string;
};

/**
 * `allow` the stop passes; `verify` run the cheap checks and ask again; `settle` run every check of the done items and ask again; `block` refuse the stop with `reason`
 */
export type TodoStopAction = 'allow' | 'verify' | 'settle' | 'block' | (string & {});

/**
 * The server's answer to a stop
 */
export type TodoStopDecision = {
    action: TodoStopAction;
    todo?: Todo;
    /**
     * `block`: the resume message for the agent, at most 8 000 characters
     */
    reason?: string;
    /**
     * `allow`: `no_list`, `hook_disabled`, `finished`, `background_task`, `wait_open`, `settled` or `escalated`
     */
    why?: string;
    /**
     * The third stop without progress opened a wait for the owner (false when absent)
     */
    escalated?: boolean;
};

export type ResetTodoRequest = {
    /**
     * The session, named by its owner or by its agent token
     */
    sessionId?: string;
};

export type TodoHookErrorRequest = {
    sessionId?: string;
    /**
     * What failed, kept to 500 characters
     */
    text: string;
};

export type TodoStopHookRequest = {
    /**
     * true to hold the agent while its todo has open items
     */
    enabled: boolean;
};

/**
 * The todo Stop hook setting of a member; a member without one has it on
 */
export type TodoStopHook = {
    /**
     * The member's id (`Member.id`)
     */
    memberId: string;
    enabled: boolean;
};

export type TodoStopHooks = {
    /**
     * Every member of the organization whose hook is off
     */
    members: Array<TodoStopHook>;
};

/**
 * Spending over a period
 */
export type Usage = {
    from: string;
    to: string;
    usd: number;
    tokensIn: number;
    tokensOut: number;
    byMember?: {
        [key: string]: number;
    };
    byModel?: {
        [key: string]: number;
    };
    cacheReadTokens: number;
    cacheWriteTokens: number;
    events: number;
};

/**
 * A usage event; costs in millionths of a US dollar
 */
export type UsageEvent = {
    id: string;
    memberId?: string;
    /**
     * `model`, `mcp`, `skill`, `hook` or `session`
     */
    kind: string;
    name: string;
    provider?: string;
    accountId?: string;
    sessionId?: string;
    /**
     * The launch whose agent token made the call or sent the event, set by the server from the token (`POST /launches`), never from a request body; absent for a person's own credential. Read under the same rules as the event
     */
    launchId?: string;
    inputTokens: number;
    outputTokens: number;
    cacheReadTokens: number;
    cacheWriteTokens: number;
    costMicros: number;
    durationMillis: number;
    outcome: string;
    at: string;
};

/**
 * An event a client declares
 */
export type UsageEventInput = {
    kind: 'skill' | 'hook' | 'session' | 'mcp' | (string & {});
    /**
     * The skill, the hook event, the session id or `server/tool`
     */
    name: string;
    sessionId?: string;
    durationMillis?: number;
    /**
     * `ok` or a short error key
     */
    outcome?: string;
    /**
     * ISO 8601; now when absent
     */
    at?: string;
};

/**
 * Totals per group since a date
 */
export type UsageSummary = {
    since: string;
    groupBy: string;
    groups: Array<UsageTotal>;
    total: UsageTotal;
};

/**
 * The totals of a group; `key` is absent for the total and for events without one
 */
export type UsageTotal = {
    key?: string;
    events: number;
    inputTokens: number;
    outputTokens: number;
    cacheReadTokens: number;
    cacheWriteTokens: number;
    costMicros: number;
};

/**
 * Result of an offline-equivalent receipt verification
 */
export type Verification = {
    ok: boolean;
    digest?: string;
    kid?: string;
    reason?: string;
    /**
     * Whether the signed body names the organization that verifies it. `ok` says only that the signature holds: a client that relies on the receipt being this organization's checks `orgBound` is true, and reads an absent `orgBound` (a server that predates it) as not bound. False for a receipt signed before `Receipt.orgId`: valid, shown as not bound to an organization, never accepted as this organization's. A receipt that names another organization is not ok, with a `reason` that names no organization. Planned
     */
    orgBound?: boolean;
};

/**
 * A page of waits; `next` is the cursor of the following page
 */
export type WaitPage = {
    items: Array<Wait>;
    next?: string;
};

/**
 * An answer to a wait: one of its actions and the values of its fields
 */
export type AnswerWaitRequest = {
    action: string;
    values?: {
        [key: string]: unknown;
    };
};

/**
 * A wait: a question to a person, asked by an agent (`ask_human`) or by a wait node of a run. First answer wins
 */
export type Wait = {
    id: string;
    kind: string;
    status: WaitStatus;
    sessionId?: string;
    runId?: string;
    assignee: string;
    createdBy?: string;
    question: WaitSpec;
    answer?: WaitAnswer;
    createdAt: string;
    resolvedAt?: string;
    /**
     * `human` (absent means `human`), `time` or `event`: who resolves it
     */
    resolver?: string;
    /**
     * `time`: when it resolves
     */
    dueAt?: string;
    /**
     * `event`: when it resolves as timed out if nothing arrived
     */
    timeoutAt?: string;
    /**
     * `event`: where the event comes from (`webhook`)
     */
    eventSource?: string;
    /**
     * `time` or `event`: the line added to the message that wakes the session
     */
    resumeMessage?: string;
    /**
     * `event` with `source: webhook`, in the answer that creates it only: the address a CI or a script calls (`POST /api/v1/waits/{id}/event?token=wev_…`). It holds the wait's secret, never shown again
     */
    eventUrl?: string;
};

/**
 * What an outside caller posts to an `event` wait: data for the agent, never instructions
 */
export type WaitEventRequest = {
    /**
     * `success` or `failure` by convention; `success` by default
     */
    result?: string;
    /**
     * An https link (a CI run, a deployment)
     */
    url?: string;
    note?: string;
};

/**
 * The wait the event resolved
 */
export type WaitEventReceived = {
    id: string;
    status: WaitStatus;
};

/**
 * How long the server may hold the answer back
 */
export type WaitWakeRequest = {
    waitMillis?: number;
};

/**
 * What the waits of a session have to say to its Stop hook
 */
export type WaitWake = {
    /**
     * A wait asked by the session is still open
     */
    open: boolean;
    /**
     * The answers that arrived, oldest first, each handed over once
     */
    messages: Array<string>;
};

/**
 * A button of a wait
 */
export type WaitAction = {
    id: string;
    label: string;
    requires?: Array<string>;
    style?: string;
};

/**
 * The answer to a wait
 */
export type WaitAnswer = {
    action: string;
    values?: {
        [key: string]: unknown;
    };
    author: string;
    answeredAt: string;
};

/**
 * A field of a wait
 */
export type WaitField = {
    id: string;
    type: string;
    label: string;
    help?: string;
    required?: boolean;
    default?: unknown;
    options?: Array<string>;
    multiple?: boolean;
    allowOther?: boolean;
    maxLength?: number;
};

/**
 * A link shown with a wait
 */
export type WaitRef = {
    kind: string;
    id?: string;
    url?: string;
    title?: string;
};

/**
 * The question of a wait node, or of a wait asked by an agent (TeamCode `ask_human`)
 */
export type WaitSpec = {
    title: string;
    body?: string;
    fields?: Array<WaitField>;
    actions?: Array<WaitAction>;
    refs?: Array<WaitRef>;
};

export type WaitStatus = 'open' | 'resolved' | 'cancelled' | (string & {});

/**
 * An outgoing webhook of the organization. Each event of `types` is POSTed to `url` as JSON `{id, type, createdAt, data}`, `data` being the `OrgEvent` (`{"message": ...}` for `webhook.test`), with the headers `Ostrom-Delivery` (one id per event and webhook, the same on every retry: deduplicate on it), `Ostrom-Event`, `Ostrom-Timestamp` (Unix seconds) and `Ostrom-Signature: v1=<hex>`, the HMAC-SHA256 of `<timestamp>.<raw body>` keyed with the whole `whsec_` secret. A receiver compares in constant time and rejects a timestamp more than five minutes old. The body is fixed when the event is queued: every retry sends the same bytes, only the timestamp and the signature are fresh. A 2xx within 10 seconds is a delivery; a network error, a timeout, a 5xx, 408 or 429 is retried, 8 attempts in all, after 10 s, 30 s, 2 min, 10 min, 30 min, 2 h and 6 h; any other answer (a 4xx, a redirect) is final. A delivery still pending after 24 hours is given up (`expired`). Twenty final failures in a row disable the webhook (`too_many_failures`); a success resets the count. Deliveries are not ordered: use `data.seq` when order matters.
 */
export type Webhook = {
    id: string;
    url: string;
    /**
     * The event types it receives, sorted
     */
    types: Array<string>;
    description: string;
    enabled: boolean;
    /**
     * `disabled` (paused by a person) or `too_many_failures`; absent while enabled
     */
    disabledReason?: string;
    /**
     * The member who created it
     */
    createdBy: string;
    createdAt: string;
    updatedAt: string;
    /**
     * Sent back by `updateWebhook`
     */
    version: number;
    /**
     * Final failures in a row since the last success
     */
    consecutiveFailures: number;
};

export type WebhookList = {
    items: Array<Webhook>;
};

/**
 * A webhook and its signing secret, in the answer to its creation or a rotation only
 */
export type CreatedWebhook = {
    webhook: Webhook;
    /**
     * `whsec_…`; store it now, it is never readable again
     */
    secret: string;
};

export type CreateWebhookRequest = {
    url: string;
    types: Array<string>;
    description?: string;
};

export type UpdateWebhookRequest = {
    version: number;
    url: string;
    types: Array<string>;
    description?: string;
    /**
     * Absent keeps the current state
     */
    enabled?: boolean;
};

/**
 * One event for one webhook, and its attempts
 */
export type WebhookDelivery = {
    /**
     * Also the `Ostrom-Delivery` header
     */
    id: string;
    /**
     * The event's `seq`; absent for a test
     */
    eventSeq?: number;
    eventType: string;
    /**
     * `pending`, `delivered` or `failed`
     */
    state: string;
    attempts: number;
    /**
     * While pending
     */
    nextAttemptAt?: string;
    /**
     * The last HTTP status the receiver answered
     */
    lastStatus?: number;
    /**
     * `timeout`, `connect`, `tls`, `dns`, `host_not_allowed`, `secret_unreadable` or `expired`
     */
    lastError?: string;
    createdAt: string;
    deliveredAt?: string;
    test: boolean;
};

export type WebhookDeliveryList = {
    items: Array<WebhookDelivery>;
};

/**
 * A workflow
 */
export type Workflow = {
    id: string;
    name: string;
    domain: string;
    description?: string;
    version?: number;
    /**
     * Repositories the workflow applies to, `owner/name` where `*` is any part of a name (1 to 100). Absent: every repository of the organization, as before. Present: these only, whether the workflow is observed or enforced, in the session packages and the gates catalogue
     */
    repos?: Array<string>;
    nodes: Array<WorkflowNode>;
    edges: Array<WorkflowEdge>;
    start?: string;
    inputs?: Array<WorkflowInput>;
    /**
     * `same`: the agent steps of a run are messages of one session; `handoff` (when absent): each agent step starts a session whose first message carries what the earlier steps delivered
     */
    sessionMode?: string;
    limits?: WorkflowLimits;
    sources?: Array<RuleSource>;
    status: WorkflowStatus;
    foundAt: string;
    updatedAt?: string;
    updatedBy?: string;
};

/**
 * An edge. For a run, [on] is the outcome that follows it (`next`, `delivered`, a wait action id, `true` or `false` out of a check node with a condition, which has no default); [to] null ends
 */
export type WorkflowEdge = {
    from: string;
    to: string | null;
    label?: string;
    on?: string;
};

/**
 * Who may decide workflows besides owners and admins
 */
export type WorkflowEditors = {
    /**
     * `all`, `admins` (the default) or `members`
     */
    mode: string;
    /**
     * The members who may, with `members` (`Member.id`)
     */
    memberIds?: Array<string>;
};

/**
 * An input of a workflow run
 */
export type WorkflowInput = {
    id: string;
    label: string;
    required?: boolean;
    default?: string;
    maxLength?: number;
};

/**
 * The bounds of a run of the workflow: `maxNodes` (50, at most 100), `maxVisits` in all (100, at most 500), `maxDepth` of sub-workflows (3, at most 5)
 */
export type WorkflowLimits = {
    maxNodes?: number;
    maxVisits?: number;
    maxDepth?: number;
};

/**
 * A workflow node
 */
export type WorkflowNode = {
    id: string;
    kind: WorkflowNodeKind;
    label: string;
    detail?: string;
    owner?: string;
    approvers?: Array<string>;
    approverReason?: string;
    when?: NodeWhen;
    ruleIds?: Array<string>;
    position?: NodePosition;
    actions?: Array<GateAction>;
    actionsBy?: string;
    actionsAt?: string;
    run?: NodeRun;
    suggested?: NodeSuggestions;
    wait?: WaitSpec;
    /**
     * The workflow a `workflow` node runs: a child run of another accepted workflow of the organization, with `arguments` as its inputs. A run never calls a workflow already running above it, and runs nest at most 5 deep: the visit fails then, and the run ends `failed`, with the reason in `failure` (no HTTP error: the call is checked when the run reaches it, since the called workflow may change after it is saved)
     */
    workflowId?: string;
    arguments?: {
        [key: string]: string;
    };
    maxVisits?: number;
    condition?: NodeCondition;
};

export type WorkflowNodeKind = 'trigger' | 'step' | 'check' | 'gate' | 'notify' | 'agent' | 'wait' | 'workflow' | (string & {});

/**
 * The form of a pending deliverable, never its schema
 */
export type WorkflowPendingDeliverable = {
    type: string;
    domain?: string;
};

/**
 * A workflow run
 */
export type WorkflowRun = {
    id: string;
    workflowId: string;
    workflowName: string;
    workflowVersion: number;
    status: RunStatus;
    startedBy: string;
    source: string;
    automationId?: string;
    inputs?: {
        [key: string]: string;
    };
    currentNodeId?: string;
    currentNodeKind?: WorkflowNodeKind;
    parentRunId?: string;
    sessionId?: string;
    /**
     * The repository of the agent nodes that name none
     */
    repository?: string;
    visits?: Array<NodeVisit>;
    failure?: string;
    /**
     * A stable code: `session_failed`, `session_deleted`, `session_missing`, `ended_without_delivery`, `repository_missing`, `starter_unavailable`, `wait_cancelled`, `wait_missing`, `max_visits:<node>`, `max_total_visits`, `max_depth`, `workflow_missing`, `invalid_arguments`, `sub_workflow_failed`, `sub_workflow_cancelled`, `expired`, `no_transition`, or the code of a refusal that cannot be retried
     */
    failureCode?: string;
    output?: string;
    receiptId?: string;
    startedAt: string;
    endedAt?: string;
};

/**
 * Whether a session's agent step still waits for its delivery (`pendingWorkflowSession`)
 */
export type WorkflowSessionPending = {
    needsAction: boolean;
    runId?: string;
    nodeTitle?: string;
    deliverable?: WorkflowPendingDeliverable;
};

/**
 * The editing rights of workflows, and the caller's
 */
export type WorkflowSettings = {
    editors: WorkflowEditors;
    /**
     * Whether the caller may decide a workflow without a gate node
     */
    canEdit: boolean;
};

/**
 * `rejected`: a proposal a person turned down, kept so the analysis never proposes it again; it compiles nothing and never runs
 */
export type WorkflowStatus = 'proposed' | 'accepted' | 'edited' | 'rejected' | (string & {});

/**
 * An MCP server relayed by Ostrom; its credentials stay on the server
 */
export type McpServerWritable = {
    /**
     * 1 to 64 characters; `servers`, `settings`, `calls`, `usage` and `hosted` are reserved (they are paths of this API), and so is a name agents would see as one of Ostrom's own MCP servers, which every agent already has (`ostrom`, `ostrom-workflow` and `workflow`, since the launcher labels a server `ostrom-<name>` and keeps a name that starts with `ostrom`), whatever their case and surrounding spaces; a reserved name is refused with a 400
     */
    name: string;
    /**
     * The upstream URL of an HTTP server; absent for a stdio server. In answers, a stdio server reads `stdio:<launcher>:<package>`, and a member's list (`mine=true`) gives the relay path, never the upstream
     */
    url?: string;
    /**
     * http, sse or stdio
     */
    transport: string;
    /**
     * The org secrets the server uses, in an admin's list only
     */
    secretNames?: Array<string>;
    tools?: Array<string>;
    enabled: boolean;
    scope: string;
    /**
     * The header carrying the credential, when not `Authorization: Bearer`
     */
    credentialHeader?: string;
    stdio?: McpStdioSpec;
};

/**
 * A shared subscription account of TeamCode, tokens in clear (sent once, over TLS)
 */
export type TeamCodeAccountWritable = {
    provider: 'claude' | 'codex' | (string & {});
    providerAccountId: string;
    label: string;
    email?: string;
    accessToken: string;
    refreshToken: string;
    expiresAt: string;
    disabled?: boolean;
};

/**
 * A TeamCode member's assignment to an MCP variant
 */
export type TeamCodeAssignmentWritable = {
    memberId: string;
    /**
     * TeamCode's variant id
     */
    serverId: string;
    /**
     * The member's own credential, in clear
     */
    memberSecret?: string;
};

/**
 * What `ostrom import teamcode` read from TeamCode (read-only there), and its member map
 */
export type TeamCodeImportRequestWritable = {
    members?: Array<TeamCodeMember>;
    mcpServers?: Array<TeamCodeMcpServerWritable>;
    assignments?: Array<TeamCodeAssignmentWritable>;
    accounts?: Array<TeamCodeAccountWritable>;
    /**
     * TeamCode's workflows (planned with `workflows.deliver.v1`)
     */
    workflows?: Array<TeamCodeWorkflow>;
    workflowEditors?: TeamCodeWorkflowEditors;
    /**
     * TeamCode's automations, without their secrets (planned)
     */
    automations?: Array<TeamCodeAutomation>;
    /**
     * The cloud profiles the workflows and automations name (planned)
     */
    profiles?: Array<TeamCodeProfile>;
    /**
     * TeamCode member id to Ostrom member id (`Member.id`); unmapped members are skipped
     */
    memberMap?: {
        [key: string]: string;
    };
};

/**
 * An MCP variant of TeamCode; a slot's most assigned variant keeps the slot's name
 */
export type TeamCodeMcpServerWritable = {
    id: string;
    /**
     * The slot, the name agents see
     */
    target: string;
    variant: string;
    perMember?: boolean;
    url?: string;
    /**
     * Absent, or Authorization, for a Bearer credential
     */
    credentialHeader?: string;
    /**
     * The shared credential, in clear
     */
    sharedSecret?: string;
    stdio?: TeamCodeStdioWritable;
    /**
     * Absent for every tool
     */
    toolMode?: 'allow' | 'deny' | (string & {});
    tools?: Array<string>;
};

/**
 * A command of TeamCode run by the MCP host
 */
export type TeamCodeStdioWritable = {
    launcher: 'npm' | 'pypi' | (string & {});
    packageName: string;
    args?: Array<string>;
    /**
     * Secret variables, values in clear; never returned nor logged
     */
    secretEnv?: {
        [key: string]: string;
    };
};

/**
 * The scheduling class of an inference call in the admission queue (`inference.queue.v1`): `interactive` (the default) or `background` (unattended work, `ostrom run --workload background`). A hint the caller sets, not a permission: it changes only the order of waiting calls. Never sent to a provider. Another value, or the header twice, is refused with 400 `invalid_workload`
 */
export type OstromWorkload = 'interactive' | 'background' | (string & {});

/**
 * The caller's own id of an inference call (`inference.cancel.v1`), a lowercase UUID, fresh for each call: `cancelInferenceRequest` with it stops the call on whichever replica runs it, queued or streaming. Never sent to a provider. Not a UUID in lowercase: 400 `invalid_request_id`
 */
export type OstromClientRequestId = string;

/**
 * `agent`: set by the CLI's local relay on every memory call it forwards for an agent, whoever's sign-in it carries (`memory.v1`). A team entry such a call writes is a proposal. Any other value is ignored
 */
export type OstromOrigin = string;

/**
 * The id of the organization the request acts in. Required when the signed-in person is a member of several organizations; without it, a person with exactly one active membership acts in that organization. Missing while several memberships are active, 409 `org_required` (`error.type`, the usual `ApiError` body); an organization the person is not a member of, 404, as for anything of another organization. A token bound to one organization (device, agent, runner, service key) acts in its own organization
 */
export type OstromOrg = string;

